// Monster Factory — Spine FX layer (skeletons generated by
// scripts/monster_factory_fx.py into img/monster-factory/fx/). Same pattern as
// js/baku-fx.js and js/ice-spin-deluxe/fx.js:
//
//   #fxBack  (under .stage)  — bg_desk / bg_mob: `idle` in the base game,
//            `bonus` in free spins (setMode).
//   #fxFront (over .stage)   — frame + logo (`idle`; `win` while a cascade
//            win is on screen; the DOM logo is hidden once the Spine one is
//            up), symbol win clips (one per code, over the cell; the caller
//            hides the DOM <img> meanwhile), burst (small win), shower (coin
//            rain over a win popup — the canvas is lifted above #screenDim via
//            body.fx-over-dim, base instances dimmed in Spine).
//
// Every instance is anchored to its DOM element, so CSS stays the only source
// of layout truth. If WebGL or an asset fails, MonsterFx.ready stays false and
// slot.js keeps its CSS animations + canvas coins (js/monster-factory/fx.js).

(function () {
  const ROOT = 'img/monster-factory/fx';
  let back = null;
  let front = null;
  const res = {};
  let bgInst = null;
  let bgVariant = null;
  let frameInst = null;
  let frameVariant = null;
  let logoInst = null;
  let burstInst = null;
  let burstTimer = null;
  let showerInst = null;
  let winOn = false;
  let mode = 'base';

  const MonsterFx = { ready: false };

  function isMobile() {
    return window.matchMedia('(orientation: portrait)').matches;
  }

  function load(stage, name) {
    if (res[name]) return Promise.resolve(res[name]);
    return SpineEngine.SpineResource.load(stage.assetManager, `${ROOT}/${name}`, { premultipliedAlpha: true })
      .then((r) => { res[name] = r; return r; });
  }

  // The generator centres every skeleton on its authored box, and that box is
  // exactly the DOM element it is anchored to.
  function make(name, anchorEl) {
    const inst = res[name].createInstance();
    const sd = res[name].skeletonData;
    inst.anchorEl = anchorEl;
    inst.fit = 1;
    inst.boundsOverride = { x: sd.x, y: sd.y, width: sd.width, height: sd.height };
    return inst;
  }

  function bgClip() {
    return mode === 'freespins' ? 'bonus' : 'idle';
  }

  function mountBg() {
    const v = isMobile() ? 'bg_mob' : 'bg_desk';
    if (v === bgVariant || !res[v]) return;
    if (bgInst) back.removeBase(bgInst);
    bgVariant = v;
    bgInst = make(v, document.getElementById('stage'));
    bgInst.play(bgClip(), true);
    back.addBase(bgInst);
  }

  function mountFrame() {
    const v = isMobile() ? 'frame_mob' : 'frame_desk';
    if (v === frameVariant || !res[v]) return;
    if (frameInst) front.removeBase(frameInst);
    frameVariant = v;
    frameInst = make(v, document.getElementById('frameLayer'));
    frameInst.play(winOn ? 'win' : 'idle', true);
    front.addBaseBehindAll(frameInst);
  }

  MonsterFx.load = function load_() {
    if (!window.spine || !window.SpineEngine) return Promise.resolve(false);
    try {
      back = new SpineEngine.SpineStage(document.getElementById('fxBack'));
      front = new SpineEngine.SpineStage(document.getElementById('fxFront'));
    } catch (err) {
      console.warn('[monster-fx] no WebGL — CSS fallback', err);
      return Promise.resolve(false);
    }
    const mob = isMobile();
    return Promise.all([
      load(back, mob ? 'bg_mob' : 'bg_desk'),
      load(front, mob ? 'frame_mob' : 'frame_desk'),
      load(front, 'logo'),
      load(front, 'symbols'),
      load(front, 'burst'),
      load(front, 'shower'),
    ]).then(() => {
      MonsterFx.ready = true;
      mountBg();
      mountFrame();
      logoInst = make('logo', document.querySelector('.logo'));
      logoInst.play('idle', true);
      front.addBase(logoInst);
      document.body.classList.add('fx-ready');
      // the other device's variants, for an orientation flip later
      load(back, mob ? 'bg_desk' : 'bg_mob').catch(() => {});
      load(front, mob ? 'frame_desk' : 'frame_mob').catch(() => {});
      window.addEventListener('resize', () => {
        Promise.all([
          load(back, isMobile() ? 'bg_mob' : 'bg_desk'),
          load(front, isMobile() ? 'frame_mob' : 'frame_desk'),
        ]).then(() => { mountBg(); mountFrame(); }).catch(() => {});
      });
      return true;
    }).catch((err) => {
      console.warn('[monster-fx] assets failed — CSS fallback', err);
      return false;
    });
  };

  MonsterFx.setMode = function setMode(next) {
    mode = next === 'freespins' ? 'freespins' : 'base';
    if (MonsterFx.ready && bgInst) bgInst.play(bgClip(), true);
  };

  MonsterFx.setWin = function setWin(on) {
    if (!MonsterFx.ready || on === winOn) return;
    winOn = on;
    const clip = on ? 'win' : 'idle';
    if (frameInst) frameInst.play(clip, true);
    if (logoInst) logoInst.play(clip, true);
  };

  // Winning symbol: a Spine copy of the tile plays its own clip (named after
  // the symbol code) over the cell. Returns the instance (the caller hides the
  // DOM <img> and calls dropSymbol when its pulse is over), or null.
  MonsterFx.symbol = function symbol(cellEl, code) {
    if (!MonsterFx.ready || !res.symbols.skeletonData.findAnimation(code)) return null;
    const inst = make('symbols', cellEl);
    inst.play(code, false);
    front.addBase(inst);
    return inst;
  };

  MonsterFx.dropSymbol = function dropSymbol(inst) {
    if (inst && front) front.removeBase(inst);
  };

  // Small win: star burst + coin fountain out of the reel window, once.
  MonsterFx.burst = function burst() {
    if (!MonsterFx.ready) return;
    if (burstInst) front.removeOverlay(burstInst);
    clearTimeout(burstTimer);
    const inst = make('burst', document.getElementById('reelGrid'));
    inst.play('win', false);
    front.addOverlay(inst);
    burstInst = inst;
    // timer, not the complete event: a hidden tab ticks no frames
    burstTimer = setTimeout(() => {
      front.removeOverlay(inst);
      if (burstInst === inst) burstInst = null;
    }, 1700);
  };

  // Win popup: coin rain over the dim. The box is a 1000x1000 square; fitting
  // it by the screen's longer side makes it cover the screen.
  MonsterFx.startShower = function startShower() {
    if (!MonsterFx.ready) return false;
    MonsterFx.stopShower();
    const screen = document.getElementById('screen');
    const inst = make('shower', screen);
    const wide = screen.clientWidth >= screen.clientHeight;
    inst.fitMode = wide ? 'width' : 'height';
    if (!wide) inst.fit = 0.55;
    inst.play('start', false);
    inst.queue('rain', true);
    showerInst = inst;
    front.addOverlay(inst);
    front.setBaseDim(true);
    document.body.classList.add('fx-over-dim');
    return true;
  };

  MonsterFx.stopShower = function stopShower() {
    if (!showerInst) return;
    front.removeOverlay(showerInst);
    showerInst = null;
    front.setBaseDim(false);
    document.body.classList.remove('fx-over-dim');
  };

  window.MonsterFx = MonsterFx;
})();
